#ifdef USECGAL

#include <stdio.h>
#include <cstdlib>

typedef struct {
	double x;
	double y;
	double z;
} point3d;

typedef struct {
	double x;
	double y;
} point2d;

extern  "C" {

  // allocate storage for integer values
  int *allocate_storage_integer(const int n){
  	// Array of point3d
	return (int *) std::malloc(sizeof(int) * n);
  }

  // allocate storage for double values
  int *allocate_storage_double(const int n){
  	// Array of point3d
	return (int *) std::malloc(sizeof(double) * n);
  }

  // allocate storage for 2d points
  int *allocate_storage_point2d(const int n){
  	// Array of point3d
  	return (int *) std::malloc(sizeof(point2d) * n);
  }

  // allocate storage for 3d points
  int *allocate_storage_point3d(const int n){
  	// Array of point3d
  	return (int *) std::malloc(sizeof(point3d) * n);
  }

  // deallocate storage of points
  void deallocate_storage(int *ptr){
	  std::free(ptr);
  }
}

#endif

